"use client";
// Extracted leaf mechanics from Syuze MemoirBook: independent paper/board
// profiles, shared angle shading, cover-centering and release velocity.
import {
  useLayoutEffect,
  useRef,
  useState,
  type CSSProperties,
  type ReactNode,
  type PointerEvent,
} from "react";
import { springFrames } from "./spring-frames";
import "./page-book.css";
export interface BookPage {
  id: string;
  content: ReactNode;
}
export interface PageBookProps {
  title: string;
  pages: BookPage[];
  cover?: ReactNode;
  coverColor?: string;
  className?: string;
  style?: CSSProperties;
  onPageChange?: (page: number) => void;
}
export function PageBook({
  title,
  pages,
  cover,
  coverColor = "var(--roc-accent, #64735f)",
  className = "",
  style,
  onPageChange,
}: PageBookProps) {
  const root = useRef<HTMLDivElement>(null),
    book = useRef<HTMLDivElement>(null),
    busy = useRef(false),
    anims = useRef<Animation[]>([]),
    generation = useRef(0);
  const [width, setWidth] = useState(500),
    [turned, setTurned] = useState(0),
    [moving, setMoving] = useState(false);
  const position = useRef(0);
  const spread = width >= 440,
    W = Math.max(80, Math.min(220, spread ? (width - 40) / 2 : width - 70)),
    H = W / 0.72,
    last = Math.ceil(pages.length / (spread ? 2 : 1));
  const live = useRef({ spread, W, last });
  live.current = { spread, W, last };
  const leaf = (i: number) =>
    root.current?.querySelector<HTMLElement>(`[data-leaf="${i}"]`);
  const shift = (angle: number) =>
    live.current.spread ? (-live.current.W / 2) * (1 + angle / 180) : 0;
  const rest = () => {
    for (let i = 0; i <= live.current.last; i++) {
      const el = leaf(i);
      if (!el) continue;
      const flipped = i < position.current;
      el.style.transform = flipped ? "rotateY(-180deg)" : "none";
      el.style.zIndex = String(flipped ? i + 1 : live.current.last + 2 - i);
      el.querySelectorAll<HTMLElement>(".roc-book-shade").forEach(
        (n) => (n.style.opacity = "0"),
      );
    }
    if (book.current)
      book.current.style.transform = `translateX(${position.current === 0 ? shift(0) : 0}px)`;
  };
  const pose = (i: number, angle: number) => {
    const el = leaf(i);
    if (!el) return;
    el.style.zIndex = "1000";
    el.style.transform = `rotateY(${angle}deg)`;
    el.querySelectorAll<HTMLElement>(".roc-book-shade").forEach(
      (n) =>
        (n.style.opacity = String(
          Math.sin((Math.abs(angle) * Math.PI) / 180) * 0.26,
        )),
    );
    if (i === 0 && book.current)
      book.current.style.transform = `translateX(${shift(angle)}px)`;
  };
  const settle = async (i: number, from: number, to: number, velocity = 0) => {
    const el = leaf(i);
    if (!el) return;
    const token = ++generation.current;
    busy.current = true;
    setMoving(true);
    pose(i, from);
    const mass = i === 0 ? 0.85 : 0.5,
      k = i === 0 ? 80 : 150;
    const samples = springFrames(
        { a: from },
        { a: to },
        { a: velocity },
        { stiffness: k, mass, damping: 2 * Math.sqrt(k * mass) },
      ),
      duration = samples.at(-1)!.time * 1000;
    if (!matchMedia("(prefers-reduced-motion: reduce)").matches) {
      const tracks = [
        { el, paint: (a: number) => ({ transform: `rotateY(${a}deg)` }) },
        ...[...el.querySelectorAll<HTMLElement>(".roc-book-shade")].map(
          (el) => ({
            el,
            paint: (a: number) => ({
              opacity: Math.sin((Math.abs(a) * Math.PI) / 180) * 0.26,
            }),
          }),
        ),
        ...(i === 0 && book.current
          ? [
              {
                el: book.current,
                paint: (a: number) => ({
                  transform: `translateX(${shift(a)}px)`,
                }),
              },
            ]
          : []),
      ];
      anims.current = tracks.map((t) =>
        t.el.animate(
          samples.map((s) => ({
            ...t.paint(s.values.a),
            offset: (s.time * 1000) / duration,
          })),
          { duration, easing: "linear", fill: "both" },
        ),
      );
      let timer: ReturnType<typeof setTimeout> | undefined;
      await Promise.race([
        Promise.all(anims.current.map((a) => a.finished.catch(() => {}))),
        new Promise((r) => {
          timer = setTimeout(r, duration + 100);
        }),
      ]);
      clearTimeout(timer);
    }
    if (token !== generation.current) return;
    rest();
    anims.current.forEach((a) => a.cancel());
    anims.current = [];
    busy.current = false;
    setMoving(false);
  };
  const step = (dir: number) => {
    if (busy.current) return;
    const i = dir > 0 ? position.current : position.current - 1;
    if (i < 0 || i > last) return;
    position.current += dir;
    setTurned(position.current);
    onPageChange?.(position.current);
    void settle(i, dir > 0 ? 0 : -180, dir > 0 ? -180 : 0);
  };
  const drag = useRef<{
    i: number;
    forward: boolean;
    x: number;
    angle: number;
    moved: boolean;
    trail: { x: number; t: number }[];
  } | null>(null);
  const down = (e: PointerEvent) => {
    if (
      busy.current ||
      (e.target as HTMLElement).closest("button,a,input,textarea,audio")
    )
      return;
    const r = book.current!.getBoundingClientRect(),
      forward = e.clientX >= r.left + (spread ? r.width / 2 : W * 0.35),
      i = forward ? position.current : position.current - 1;
    if (i < 0 || i > last) return;
    drag.current = {
      i,
      forward,
      x: e.clientX,
      angle: forward ? 0 : -180,
      moved: false,
      trail: [{ x: e.clientX, t: performance.now() }],
    };
    e.currentTarget.setPointerCapture(e.pointerId);
  };
  const move = (e: PointerEvent) => {
    const d = drag.current;
    if (!d) return;
    const dx = e.clientX - d.x;
    if (!d.moved && Math.abs(dx) < 6) return;
    d.moved = true;
    d.angle = Math.max(
      -180,
      Math.min(
        0,
        (d.forward ? 0 : -180) + (180 * dx) / (W * (spread ? 1.4 : 1)),
      ),
    );
    d.trail.push({ x: e.clientX, t: performance.now() });
    if (d.trail.length > 5) d.trail.shift();
    pose(d.i, d.angle);
  };
  const up = (cancel = false) => {
    const d = drag.current;
    drag.current = null;
    if (!d) return;
    if (cancel) {
      void settle(d.i, d.angle, d.forward ? 0 : -180);
      return;
    }
    if (!d.moved) {
      step(d.forward ? 1 : -1);
      return;
    }
    const a = d.trail[0],
      b = d.trail.at(-1)!,
      velocity =
        b.t > a.t && performance.now() - b.t < 100
          ? (((180 * (b.x - a.x)) / (b.t - a.t)) * 1000) /
            (W * (spread ? 1.4 : 1))
          : 0,
      flipped = d.angle + velocity * 0.12 < -90;
    if (d.forward === flipped) {
      position.current += d.forward ? 1 : -1;
      setTurned(position.current);
      onPageChange?.(position.current);
    }
    void settle(d.i, d.angle, flipped ? -180 : 0, velocity);
  };
  useLayoutEffect(() => {
    const observer = new ResizeObserver((entries) =>
      setWidth(entries[0].contentRect.width),
    );
    observer.observe(root.current!);
    return () => {
      observer.disconnect();
      generation.current++;
      anims.current.forEach((a) => a.cancel());
    };
  }, []);
  useLayoutEffect(() => {
    generation.current++;
    anims.current.forEach((a) => a.cancel());
    anims.current = [];
    drag.current = null;
    busy.current = false;
    setMoving(false);
    position.current = Math.min(position.current, last + 1);
    setTurned(position.current);
    rest();
  }, [spread, W, last]);
  return (
    <div
      ref={root}
      className={`roc-page-book ${className}`}
      data-mode={spread ? "spread" : "single"}
      tabIndex={0}
      aria-label={`${title}, page-turning book`}
      style={
        {
          "--book-w": `${W}px`,
          "--book-h": `${H}px`,
          "--book-color": coverColor,
          ...style,
        } as CSSProperties
      }
      onKeyDown={(e) => {
        if (
          (e.target as HTMLElement).closest("input,textarea,[contenteditable]")
        )
          return;
        if (["ArrowLeft", "ArrowRight"].includes(e.key)) {
          e.preventDefault();
          e.stopPropagation();
          step(e.key === "ArrowRight" ? 1 : -1);
        }
      }}
    >
      <div
        className="roc-book-stage"
        onPointerDown={down}
        onPointerMove={move}
        onPointerUp={() => up()}
        onPointerCancel={() => up(true)}
      >
        <div ref={book} className="roc-book">
          {Array.from({ length: last + 1 }, (_, i) => {
            const front = spread ? (i - 1) * 2 : i - 1,
              back = spread ? front + 1 : -1;
            return (
              <div key={i} data-leaf={i} className="roc-book-leaf">
                <div
                  className={`roc-book-face front ${i === 0 ? "cover" : ""}`}
                  inert={i !== turned}
                  aria-hidden={i !== turned}
                >
                  {i === 0
                    ? (cover ?? <h3>{title}</h3>)
                    : pages[front]?.content}
                  <span className="roc-book-shade" />
                </div>
                <div
                  className={`roc-book-face back ${i === 0 ? "cover" : ""}`}
                  inert={!spread || i !== turned - 1}
                  aria-hidden={!spread || i !== turned - 1}
                >
                  {i === 0 ? (
                    <small>{title}</small>
                  ) : back >= 0 ? (
                    pages[back]?.content
                  ) : null}
                  <span className="roc-book-shade" />
                </div>
              </div>
            );
          })}
        </div>
      </div>
      <div className="roc-book-controls">
        <button
          type="button"
          aria-label="Previous page"
          disabled={moving || turned === 0}
          onClick={() => step(-1)}
        >
          ←
        </button>
        <span role="status">
          {turned === 0 ? "Cover" : `${turned} / ${last + 1}`}
        </span>
        <button
          type="button"
          aria-label="Next page"
          disabled={moving || turned > last}
          onClick={() => step(1)}
        >
          →
        </button>
      </div>
    </div>
  );
}

import { sampleSpring, type SpringOptions } from "./physical-spring";
/** Vector spring samples; settle by position AND speed, then commit an exact destination. */
export function springFrames(
  from: Record<string, number>,
  to: Record<string, number>,
  velocity: Record<string, number> = {},
  options: Partial<SpringOptions> & { fps?: number } = {},
) {
  const fps = options.fps || 120,
    frames = [],
    keys = Object.keys(to);
  let quiet = 0;
  // WAAPI interpolates linearly between samples. A coarse initial segment would
  // visibly discard incoming speed during a high-acceleration reversal.
  const times = [
    ...new Set([
      0,
      0.001,
      0.002,
      0.004,
      ...Array.from({ length: fps * 4 }, (_, i) => (i + 1) / fps),
    ]),
  ].sort((a, b) => a - b);
  for (const time of times) {
    const values: Record<string, number> = {},
      speeds: Record<string, number> = {};
    let resting = true;
    for (const key of keys) {
      const s = sampleSpring(
        from[key],
        to[key],
        velocity[key] || 0,
        time,
        options,
      );
      values[key] = s.position;
      speeds[key] = s.velocity;
      const tolerance = key.startsWith("s")
        ? 0.0001
        : key === "angle"
          ? 0.0001
          : 0.03;
      resting &&=
        Math.abs(s.position - to[key]) < tolerance &&
        Math.abs(s.velocity) < tolerance * 10;
    }
    frames.push({ time, values, velocity: speeds });
    quiet = resting ? quiet + 1 : 0;
    if (quiet >= 3) break;
  }
  const last = frames.at(-1)!;
  last.values = { ...to };
  last.velocity = Object.fromEntries(keys.map((key) => [key, 0]));
  return frames;
}

// Extracted from Franklin Board React worktree; MIT. See SOURCE-LICENSE.txt.
export interface SpringOptions {
  stiffness: number;
  damping: number;
  mass: number;
}
export const DEFAULT_SPRING: SpringOptions = {
  stiffness: 400,
  damping: 38,
  mass: 1,
};
// Typed port of the retained legacy analytic spring; legacy source stays unchanged.
export function sampleSpring(
  from: number,
  to: number,
  velocity: number,
  seconds: number,
  options: Partial<SpringOptions> = {},
) {
  const {
    stiffness: k,
    damping: c,
    mass: m,
  } = { ...DEFAULT_SPRING, ...options };
  if (!(k > 0 && m > 0 && c >= 0))
    throw new RangeError("Invalid spring parameters");
  const t = Math.max(0, seconds),
    a = c / (2 * m),
    w2 = k / m,
    d = from - to;
  let x, v;
  if (Math.abs(a * a - w2) < 1e-7) {
    const b = velocity + a * d,
      e = Math.exp(-a * t);
    x = (d + b * t) * e;
    v = (b - a * (d + b * t)) * e;
  } else if (a * a < w2) {
    const w = Math.sqrt(w2 - a * a),
      b = (velocity + a * d) / w;
    const e = Math.exp(-a * t),
      cos = Math.cos(w * t),
      sin = Math.sin(w * t);
    x = e * (d * cos + b * sin);
    v = e * ((b * w - a * d) * cos - (d * w + a * b) * sin);
  } else {
    const q = Math.sqrt(a * a - w2),
      r1 = -a + q,
      r2 = -a - q;
    const b1 = (velocity - r2 * d) / (r1 - r2),
      b2 = d - b1;
    x = b1 * Math.exp(r1 * t) + b2 * Math.exp(r2 * t);
    v = r1 * b1 * Math.exp(r1 * t) + r2 * b2 * Math.exp(r2 * t);
  }
  return { position: to + x, velocity: v };
}

export type ContainerMotion =
  | "unfold"
  | "refold"
  | "pullReturn"
  | "dropGather"
  | "dropSink"
  | "lidOpen"
  | "lidClose";
/** Same parameter families as legacy src/spring.js; deterministic midpoint by default. */
export function containerSpring(
  kind: ContainerMotion,
  random = () => 0.5,
): SpringOptions {
  if (kind === "dropGather" || kind === "dropSink") {
    const mass =
      (kind === "dropGather"
        ? 0.24 + 0.08 * random()
        : 0.16 + 0.16 * random()) * 0.48;
    return { stiffness: 100, damping: 2 * Math.sqrt(100 * mass), mass };
  }
  if (kind === "unfold")
    return { stiffness: 240, damping: 20, mass: 0.8 + 0.16 * random() };
  if (kind === "refold") {
    const mass = 0.12 + 0.12 * random();
    return { stiffness: 100, damping: 2 * Math.sqrt(100 * mass), mass };
  }
  if (kind === "pullReturn")
    return { stiffness: 400, damping: 24, mass: (0.8 + 0.4 * random()) * 0.64 };
  if (kind === "lidOpen") return { stiffness: 100, damping: 10, mass: 0.64 };
  return { stiffness: 100, damping: 2 * Math.sqrt(100 * 0.32), mass: 0.32 };
}

/** Legacy document/image presentation profile: critically damped, softer opening. */
export function presentationSpring(opening: boolean): SpringOptions {
  const mass = opening ? 0.48 : 0.32;
  return { stiffness: 100, mass, damping: 2 * Math.sqrt(100 * mass) };
}

@import "./surface.css";
.roc-page-book {
  width: 100%;
  outline-offset: 4px;
  color: #30312c;
}
.roc-book-stage {
  height: calc(var(--book-h) + 18px);
  display: grid;
  place-items: center;
  touch-action: pan-y;
  user-select: none;
  cursor: grab;
  perspective: 1800px;
}
.roc-book {
  position: relative;
  width: calc(var(--book-w) * 2);
  height: var(--book-h);
  transform-style: preserve-3d;
}
.roc-page-book[data-mode="single"] .roc-book {
  width: var(--book-w);
}
.roc-book-leaf {
  position: absolute;
  inset: 0 0 0 50%;
  transform-origin: 0 50%;
  transform-style: preserve-3d;
}
.roc-page-book[data-mode="single"] .roc-book-leaf {
  left: 0;
}
.roc-book-face {
  position: absolute;
  inset: 0;
  overflow: hidden;
  background: var(--roc-paper, #fcfbf8);
  border: 1px solid #dedcd4;
  border-radius: 3px;
  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
  padding: 22px;
  box-sizing: border-box;
  font:
    13px/1.7 Georgia,
    serif;
  box-shadow: 0 5px 15px #1f251b0e;
}
.roc-book-face.back {
  transform: rotateY(180deg);
}
.roc-page-book[data-mode="single"] .roc-book-face.back {
  display: none;
}
.roc-book-face.cover {
  background: var(--book-color);
  color: #f4f1ea;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  border: 0;
  padding: 25px;
  box-shadow: inset 6px 0 #00000012;
}
.roc-book-face h3 {
  font:
    normal 25px/1.2 Georgia,
    serif;
}
.roc-book-face small {
  font: 9px/1.5 system-ui;
  letter-spacing: 0.06em;
}
.roc-book-shade {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: #1f1e1b;
  opacity: 0;
  z-index: 3;
}
.roc-book-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 20px;
  margin-top: 12px;
  font: 11px system-ui;
}
.roc-book-controls button {
  border: 0;
  background: #ffffffa0;
  border-radius: 50%;
  width: 32px;
  height: 32px;
}
.roc-book-controls button:disabled {
  opacity: 0.3;
}

/* Shared surface primitives only. Tokens inherit from the host. No page reset. */
:where(
  .roc-expand,
  .roc-folder,
  .roc-sources,
  .roc-lanes,
  .roc-tabs,
  .roc-card-preview,
  .roc-image-viewport,
  .roc-voice,
  .roc-selection-toolbar,
  .roc-page-book,
  .roc-source-tray
) {
  color: var(--roc-ink, #30332e);
  font-family: inherit;
  box-sizing: border-box;
}
:where(
    .roc-expand,
    .roc-folder,
    .roc-sources,
    .roc-lanes,
    .roc-tabs,
    .roc-card-preview,
    .roc-image-viewport,
    .roc-voice,
    .roc-selection-toolbar,
    .roc-page-book,
    .roc-source-tray
  )
  * {
  box-sizing: border-box;
}
:where(
    .roc-expand,
    .roc-folder,
    .roc-sources,
    .roc-lanes,
    .roc-tabs,
    .roc-card-preview,
    .roc-image-viewport,
    .roc-voice,
    .roc-selection-toolbar,
    .roc-page-book,
    .roc-source-tray
  )
  button {
  font: inherit;
  color: inherit;
  cursor: pointer;
}
:where(
    .roc-expand,
    .roc-folder,
    .roc-sources,
    .roc-lanes,
    .roc-tabs,
    .roc-card-preview,
    .roc-image-viewport,
    .roc-voice,
    .roc-selection-toolbar,
    .roc-page-book,
    .roc-source-tray
  )
  button:focus-visible {
  outline: 2px solid var(--roc-accent, #64735f);
  outline-offset: 3px;
}
.roc-eyebrow {
  font:
    10px/1.4 ui-monospace,
    monospace;
  letter-spacing: 0.12em;
  color: var(--roc-muted, #757b72);
}
.roc-text-button {
  border: 0;
  background: none;
  padding: 9px 0;
  font-size: 12px;
  text-align: left;
  display: inline-flex;
  gap: 20px;
  align-items: center;
}
